      ['      .________.            ', '    .\'  ._‿__.  \'.          ', '○  /  .\' .-. \'.  \\          ', '○ |  /  ( @ )  \\  |/\'o\\     ', '○ |  \\   \'-\'   /  |\\__/≈≈~  ', '   \\  \'-.__.-\'   /)))≈~~~   ', '    \'.          .\'))~~~ ~   ', '       ‾‾‾⁀‾‾‾‾   ~ ~~ ~    ', '                  ~  ~ ~    '],
