      ['   .__‿_.     ', '○  / .-. \\    ', '○ | ( @ ) o>~ ', '○  \\ `-\' /~   ', '    ‾‾⁀‾‾     '],
      ['   .__‿_.     ', '○  / .-. \\    ', '○ | ( @ ) ->- ', '○  \\ `-\' /-   ', '    ‾‾⁀‾‾     '],
      ['   ._‿__.     ', '○  / .-. \\    ', '○ | ( @ ) o>≈ ', '○  \\ `-\' /≈   ', '    ‾⁀‾‾‾     '],
