// The confirm channel (Bradley, S162): Claude tells the companion an ask is done,
// and the companion believes it only on evidence it checks itself. A citation is a
// tool call the companion observed in this session - a piece of its input, and
// words found in its OUTPUT but not in its input, so a command cannot manufacture
// its own proof (an `echo "verified"` cites itself and fails) - or words Bradley
// typed himself, for what only he can witness, such as a layout. Pure.

import type { Ask, AskWitness, Heard, Observed } from '../types'
import { cleanText, isSessionAsk, restates } from './asks'
import { DEFAULT_PERSON, onWords, personRef } from './config'

export const CONFIRM_TOOL = 'mcp__witness__confirm'
/**
 * Calls kept as evidence. 200 ran out in one long turn (S163): the read-back an early
 * ask rested on had aged out before the work was confirmed. Each entry is bounded
 * (INPUT_CAP + RESULT_HEAD + RESULT_TAIL), so 600 is at most a few MB.
 */
export const OBSERVED_CAP = 600
export const HEARD_CAP = 50
/** The head and tail of a result are kept: a test run's verdict is at its end. */
export const RESULT_HEAD = 1_500
export const RESULT_TAIL = 2_500
export const INPUT_CAP = 2_000
export const MIN_EXCERPT = 6
export const MIN_COMMAND = 3

export type Evidence =
  | { source: 'call'; command: string; excerpt: string }
  | { source: 'user'; excerpt: string }

/** `outcome: 'dropped'` (0.6.2, a field report): the user called the ask off; absent means done. */
export type ConfirmItem = { ask: string; evidence: Evidence[]; outcome?: 'dropped' }

export type Verdict = {
  ask: string
  askId: string | null
  ok: boolean
  reason: string
  refs: string[]
  dropped?: boolean
}

const INPUT_KEYS = ['command', 'query', 'file_path', 'path', 'pattern', 'id', 'page_id', 'url', 'name']

/** A tool call's input as text: its command, query or path, else the whole input as JSON. */
export function inputText(input: Readonly<Record<string, unknown>>): string {
  const picked = INPUT_KEYS.map(k => input[k]).filter((v): v is string => typeof v === 'string')
  const text = picked.length > 0 ? picked.join(' ') : JSON.stringify(input)
  return text.slice(0, INPUT_CAP)
}

export function trimResult(text: string): string {
  if (text.length <= RESULT_HEAD + RESULT_TAIL) return text
  return `${text.slice(0, RESULT_HEAD)}\n...\n${text.slice(-RESULT_TAIL)}`
}

/** Tools whose result is a subagent's report, or its launch notice (1.1). */
export const REPORT_TOOLS: ReadonlySet<string> = new Set(['Agent', 'Task', 'TaskOutput', 'Workflow'])

/**
 * A call whose output may never be cited (1.1, ruled 2026-10-09): a subagent's own call,
 * or an Agent, Task, TaskOutput or Workflow result (a Workflow's result relays its agents'
 * reports). A report is a claim the main session reads
 * back, never the read-back itself.
 */
export function isReport(o: Pick<Observed, 'tool' | 'agent'>): boolean {
  return o.agent || REPORT_TOOLS.has(o.tool)
}

/**
 * Appends one observed call, newest kept. Never the confirm tool's own, and never a
 * subagent's (1.1): nothing a subagent ran is evidence, so it would only push the main
 * loop's read-backs out of the window.
 */
export function observe(log: readonly Observed[], o: Observed): Observed[] {
  if (o.tool === CONFIRM_TOOL || o.agent) return [...log]
  const kept: Observed = { ...o, input: o.input.slice(0, INPUT_CAP), result: trimResult(o.result) }
  return [...log, kept].slice(-OBSERVED_CAP)
}

export function hear(log: readonly Heard[], h: Heard): Heard[] {
  return [...log, h].slice(-HEARD_CAP)
}

const norm = (s: string): string => cleanText(s).toLowerCase()

/**
 * Text as the model read it: an MCP result arrives JSON-encoded inside the tool-result
 * envelope, so its quotes are stored as \" or \\\" (two or three escapes deep; one level
 * was not enough, seen live in S163) and a quoted excerpt would never match. Any run of
 * backslashes before a quote or an n is undone. Applied to input and output alike, so the
 * input-must-not-contain-the-excerpt rule still binds.
 */
const unescaped = (s: string): string => s.replace(/\\+"/g, '"').replace(/\\+n/g, ' ')

/** Does `text` contain `excerpt`, as stored or with its JSON-escaped quotes undone? */
const holds = (text: string, excerpt: string): boolean =>
  norm(text).includes(excerpt) || norm(unescaped(text)).includes(excerpt)

/** The ref of the observed call or heard prompt that bears this evidence out, made after `since`; else null. */
export function bearsOut(e: Evidence, observed: readonly Observed[], heard: readonly Heard[], since: number): string | null {
  const excerpt = norm(e.excerpt)
  if (excerpt.length < MIN_EXCERPT) return null
  if (e.source === 'user') {
    const h = heard.find(x => x.at >= since && norm(x.text).includes(excerpt))
    return h === undefined ? null : `user@${h.at}`
  }
  const command = norm(e.command)
  if (command.length < MIN_COMMAND) return null
  const o = observed.find(
    x =>
      x.at >= since &&
      !x.isError &&
      x.tool !== CONFIRM_TOOL &&
      !isReport(x) &&
      holds(x.input, command) &&
      holds(x.result, excerpt) &&
      !holds(x.input, excerpt),
  )
  return o === undefined ? null : o.toolUseId
}

/** An ask by id, else by its text (exact, then a unique containment either way), ignoring dropped asks. */
export function findAsk(asks: readonly Ask[], key: string): Ask | null {
  const live = asks.filter(a => a.state !== 'dropped')
  const byId = live.find(a => a.id === key)
  if (byId) return byId
  const k = norm(key)
  if (k.length === 0) return null
  const exact = live.find(a => norm(a.text) === k)
  if (exact) return exact
  const near = live.filter(a => norm(a.text).includes(k) || k.includes(norm(a.text)))
  if (near.length > 0) return near.length === 1 ? (near[0] ?? null) : null
  // A close paraphrase, when one live ask clearly wins (a field report: five of five
  // free-text confirms missed and needed a second call). A tie at the top is never guessed.
  const scored = live.flatMap(a => {
    const share = restates(a.text, key)
    return share === null ? [] : [{ a, share }]
  })
  const top = Math.max(0, ...scored.map(x => x.share))
  const best = scored.filter(x => x.share === top)
  return best.length === 1 ? (best[0]?.a ?? null) : null
}

function judge(item: ConfirmItem, ask: Ask, observed: readonly Observed[], heard: readonly Heard[], person: string): Verdict {
  const base = { ask: item.ask, askId: ask.id, refs: [] as string[] }
  if (ask.state === 'witnessed') return { ...base, ok: true, reason: 'already witnessed' }
  if (item.evidence.length === 0) return { ...base, ok: false, reason: 'no evidence cited' }
  // A drop rests on the user alone: the model may not call off an ask on its own say.
  if (item.outcome === 'dropped' && !item.evidence.some(e => e.source === 'user')) {
    return { ...base, ok: false, reason: `a drop needs ${personRef(person)}'s own words calling the ask off (source user)` }
  }
  const refs = item.evidence.map(e => bearsOut(e, observed, heard, ask.at))
  const missing = refs.findIndex(r => r === null)
  if (missing !== -1) {
    const e = item.evidence[missing]
    const why =
      e?.source === 'user'
        ? `those words are not in any of ${personRef(person)}'s prompts since the ask was raised`
        : 'no call since the ask was raised has that input with that excerpt in its output (and not in its input)'
    return { ...base, ok: false, reason: `evidence ${missing + 1} did not check out: ${why}` }
  }
  const proved = refs.filter((r): r is string => r !== null)
  if (item.outcome === 'dropped') return { ...base, ok: true, reason: `called off ${onWords(person)}`, refs: proved, dropped: true }
  return { ...base, ok: true, reason: 'witnessed', refs: proved }
}

/** Checks every item; an ask whose every citation checks out becomes witnessed. */
export function confirmAsks(
  asks: readonly Ask[],
  items: readonly ConfirmItem[],
  observed: readonly Observed[],
  heard: readonly Heard[],
  now: number,
  person: string = DEFAULT_PERSON,
): { asks: Ask[]; verdicts: Verdict[] } {
  const verdicts: Verdict[] = items.map(item => {
    const ask = findAsk(asks, item.ask)
    if (ask === null) return { ask: item.ask, askId: null, ok: false, reason: 'no single live ask matches that', refs: [] }
    return judge(item, ask, observed, heard, person)
  })
  const passed = new Map(verdicts.filter(v => v.ok && v.askId !== null && v.refs.length > 0).map(v => [v.askId, v]))
  const next = asks.map((a): Ask => {
    const v = passed.get(a.id)
    if (v === undefined) return { ...a }
    if (v.dropped) return { ...a, state: 'dropped', calledOff: { refs: v.refs, at: now } }
    const by: AskWitness['by'] = v.refs.some(r => r.startsWith('user@')) ? 'user' : 'evidence'
    return { ...a, state: 'witnessed', witness: { by, refs: v.refs, at: now } }
  })
  return { asks: next, verdicts }
}

/** Parses the tool's input defensively; anything malformed is dropped, never thrown. */
export function parseItems(input: unknown): ConfirmItem[] {
  const raw = (input as { items?: unknown })?.items
  if (!Array.isArray(raw)) return []
  return raw.flatMap(item => {
    const ask = (item as { ask?: unknown })?.ask
    const ev = (item as { evidence?: unknown })?.evidence
    if (typeof ask !== 'string' || !Array.isArray(ev)) return []
    const evidence = ev.flatMap((e): Evidence[] => {
      const x = e as { source?: unknown; command?: unknown; excerpt?: unknown }
      if (typeof x?.excerpt !== 'string') return []
      if (x.source === 'user') return [{ source: 'user', excerpt: x.excerpt }]
      if (x.source === 'call' && typeof x.command === 'string') return [{ source: 'call', command: x.command, excerpt: x.excerpt }]
      return []
    })
    const dropped = (item as { outcome?: unknown })?.outcome === 'dropped'
    return [dropped ? { ask, outcome: 'dropped' as const, evidence } : { ask, evidence }]
  })
}

/** The tool's answer to the model: one line per item, then the asks still undone with their ids. */
export function confirmReport(verdicts: readonly Verdict[], asks: readonly Ask[], closeName = '/close'): string {
  const head = (v: Verdict) => (!v.ok ? 'NOT WITNESSED' : v.dropped ? 'DROPPED' : 'WITNESSED')
  const lines = verdicts.map(v => `${head(v)} - ${v.ask}: ${v.reason}`)
  // A build is held for /close, never listed as this session's undone work (0.6.0), and a
  // carried ask is the last watch's, listed apart so it is never read as this session's.
  const undoneHere = (a: Ask) => a.settled === undefined && (a.state === 'open' || a.state === 'claimed')
  const open = asks.filter(a => isSessionAsk(a) && undoneHere(a))
  const carried = asks.filter(a => a.source === 'carried' && undoneHere(a))
  const builds = asks.filter(a => a.source === 'build' && a.state !== 'dropped').length
  const row = (a: Ask) => `  ${a.id}: ${a.text}`
  const tail =
    open.length > 0
      ? ['Still undone:', ...open.map(row)]
      : [carried.length > 0 ? 'Nothing undone this session.' : 'Nothing undone.']
  const fromLast = carried.length === 0 ? [] : ['Carried in from the last watch (not counted in asks n/m):', ...carried.map(row)]
  const held = builds === 0 ? [] : [`(${builds} build${builds === 1 ? '' : 's'} held for ${closeName}, to become to-dos)`]
  return [...lines, ...tail, ...fromLast, ...held].join('\n')
}

/** The confirm tool's input schema, naming the person as the model reads it. */
export function confirmSchema(person: string): Record<string, unknown> {
  const who = personRef(person)
  return {
  type: 'object',
  properties: {
    items: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          ask: { type: 'string', description: 'The ask id, or its text as /undone shows it.' },
          outcome: {
            type: 'string',
            enum: ['done', 'dropped'],
            description:
              `done (the default): the work is done, cite read-backs. dropped: ${who} called the ask off; cite those words (source user), the only evidence a drop takes.`,
          },
          evidence: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                source: { type: 'string', enum: ['call', 'user'] },
                command: {
                  type: 'string',
                  description: 'source call: a piece of the input of a tool call made in this session (the Bash command, the SQL, the path).',
                },
                excerpt: {
                  type: 'string',
                  description: `call: words from that call's OUTPUT that are not in its input. user: words ${who} typed in one of their prompts.`,
                },
              },
              required: ['source', 'excerpt'],
            },
          },
        },
        required: ['ask', 'evidence'],
      },
    },
  },
  required: ['items'],
  }
}

export const CONFIRM_SCHEMA: Record<string, unknown> = confirmSchema(DEFAULT_PERSON)

/** The confirm tool's description, naming the person as the model reads it. */
export function confirmDescription(person: string): string {
  const who = personRef(person)
  return (
  'Tell the witness companion that undone asks are done, with evidence it checks itself. ' +
  'Confirm an ask in the same turn as its read-back, before calling it done: a later bulk confirm redoes the read-backs. ' +
  'For each ask cite evidence from a read-back made AFTER the ask was raised: ' +
  '{source:"call", command:<a piece of a tool call\'s input from this session>, excerpt:<words in that call\'s output, not in its input>}, ' +
  `or, for what only ${who} can witness (a layout), {source:"user", excerpt:<words ${who} typed>}. ` +
  `Only the first ${RESULT_HEAD} and last ${RESULT_TAIL} characters of an output are kept, ` +
  'so cite a short read-back (a grep or narrow query of the passage), never the middle of a long one. ' +
  'Every citation must check out or the ask stays undone; a claim is not evidence, ' +
  "nor is a subagent's report or its own calls (an Agent, Task or TaskOutput result): read back what it changed. " +
  `When ${who} called an ask off, pass outcome "dropped" with those words as {source:"user"} evidence: ` +
  'the ask is then neither done nor undone, and never carried. Never drop an ask on your own judgement.'
  )
}

export const CONFIRM_DESCRIPTION = confirmDescription(DEFAULT_PERSON)

/** Most asks one note names; the rest wait for the next. */
export const NOTE_MAX_ASKS = 5

/**
 * The one line put to Claude on Bradley's next prompt when a turn ended with asks it
 * called done but never proved (Bradley, S165, option B): about 40 tokens, once per ask,
 * against a /tackle sweep that redoes the read-backs later.
 */
export function unprovedNote(asks: ReadonlyArray<{ id: string; text: string }>): string {
  // Each with its id, so one confirm call closes it (a field report: the model cannot run /undone).
  const list = asks
    .slice(0, NOTE_MAX_ASKS)
    .map(a => `${a.id}: "${a.text}"`)
    .join('; ')
  return `witness: claimed done but not proved by a read-back: ${list}. Read each back and confirm it with ${CONFIRM_TOOL} in this turn, citing the id.`
}

files.hooks/notes.ts:
// Two sections of the Witness print, ruled by Bradley in S163 (2026-10-07):
//
// - "Notes taken": what the witness itself SAW this watch - writes it held and how they
//   were answered, friction (cancelled writes, repeated failures, re-edits), and what it
//   said in its bubble. Built only from ledgers it already keeps; nothing is extracted.
// - "Hook and skill candidates": a side pass reads recurring friction and the session's
//   call digest and proposes "this could be a hook" (an event-bound guard or check) or
//   "this could be a skill" (a repeated multi-step procedure), each with its evidence.
//   Listed in the print and appended to one running file. Proposals only: the witness
//   never builds a hook or a skill. Pure.

import type { Candidate, Friction, Observed, Spoken } from '../types'
import { cleanText, normalise, parseJsonObject } from './asks'

export const SPOKEN_CAP = 60
export const NOTES_CAP = 25
export const MAX_CANDIDATES = 5
export const CANDIDATES_KEPT = 40
/** The candidate pass runs at most this often, and only after this many new calls. */
export const CANDIDATE_SCAN_MS = 30 * 60_000
export const CANDIDATE_MIN_NEW_CALLS = 25
export const DIGEST_CALLS = 150
const DIGEST_CHARS = 100
const TITLE_CHARS = 80
const WHY_CHARS = 160
const EVIDENCE_CHARS = 200

/** Headers that are not notes: the print announcing itself. */
const NOT_A_NOTE = new Set(['PRINT'])

const one = (text: string, max: number): string => {
  const t = cleanText(text)
  return t.length <= max ? t : `${t.slice(0, max - 3)}...`
}

/** Records one thing the companion said; an immediate repeat collapses, the newest are kept. */
export function noteSpoken(log: readonly Spoken[], said: Spoken): Spoken[] {
  const last = log[log.length - 1]
  if (last !== undefined && last.header === said.header && last.text === said.text) return [...log]
  return [...log, { ...said }].slice(-SPOKEN_CAP)
}

/** The header a note from beneath is recorded under. */
export const HEADS_UP = 'HEADS UP'

/** Records a note heard from beneath once per watch: one already in the log, anywhere, is not added again. */
export function noteHeard(log: readonly Spoken[], said: Spoken): Spoken[] {
  const seen = log.some(x => x.header === said.header && x.text === said.text)
  return seen ? [...log] : [...log, { ...said }].slice(-SPOKEN_CAP)
}

function frictionLine(f: Friction): string {
  const key = one(f.key, 120)
  const detail = one(f.detail, 160)
  switch (f.kind) {
    case 'cancelled-write':
      return `- held or cancelled write: ${key} - ${detail}`
    case 'let-through':
      return `- let through once: ${key} - ${detail}`
    case 'returning-added':
      return `- held, RETURNING added: ${key} - ${detail}`
    case 'tool-failure':
      return `- repeated failure: ${key} - ${detail}`
    case 're-edit':
      return `- re-edited three times: ${key}`
  }
}

/** The "Notes taken" lines for the print: this watch only, one line per note. */
export function notesSection(o: { friction: readonly Friction[]; spoken: readonly Spoken[]; since: number }): string[] {
  const events = [
    ...o.friction.filter(f => f.at >= o.since).map(f => ({ at: f.at, line: frictionLine(f) })),
    ...o.spoken
      .filter(x => x.at >= o.since && !NOT_A_NOTE.has(x.header))
      .map(x => ({ at: x.at, line: `- said (${one(x.header, 40)}): ${one(x.text, 200)}` })),
  ].sort((a, b) => a.at - b.at)
  const lines = [...new Set(events.map(e => e.line))]
  const head = ['### Notes taken', '']
  if (lines.length === 0) return [...head, '- Nothing noted.']
  const kept = lines.slice(0, NOTES_CAP)
  const more = lines.length - kept.length
  return more > 0 ? [...head, ...kept, `- ... and ${more} more`] : [...head, ...kept]
}

/** This session's main-session calls, one short line each, newest last. */
export function callDigest(observed: readonly Observed[], max = DIGEST_CALLS): string[] {
  return observed
    .filter(o => !o.agent)
    .slice(-max)
    .map(o => one(`${o.tool}: ${o.input}`, DIGEST_CHARS))
}

/** Installed slash commands the candidate pass is shown, at most, and each description's length. */
export const MAX_INSTALLED = 80
const INSTALLED_DESC = 90

/**
 * One installed guard or mod. `covers`: term sets, any one of which, all its terms found
 * (lowercase substrings) in a hook candidate's title and why, means the guard already does it.
 */
export type Guard = {
  name: string
  where: string
  does: string
  covers: ReadonlyArray<readonly string[]>
  disabled?: boolean
}

/**
 * The installed guards and mods (to-do 3f23...b0be, second half), from the wired-hooks
 * table in ~/.claude/rules/common/hooks.md and the estate's CLAUDE.md "Supabase write
 * paths". Static: edit it when a guard or a mod is wired, unwired or retired.
 */
export const INSTALLED_GUARDS: readonly Guard[] = [
  { name: 'shell-guard.py', where: 'PreToolUse Bash|PowerShell (managed)', does: 'blocks heredoc and here-string writes to a file, .env clobbers, and git add -A / git add . / git commit -a', covers: [['heredoc'], ['here-string'], ['.env'], ['git add -a'], ['git add .'], ['commit -a']] },
  { name: 'agent-contract.py', where: 'PreToolUse, all tools (managed)', does: "binds a subagent to its contract in agent-contracts.json: paths, tools, call and wall-clock budgets", covers: [['agent contract'], ['subagent', 'path'], ['subagent', 'budget'], ['subagent', 'forbidden']] },
  { name: 'agent-contract.py', where: 'SubagentStart, SubagentStop (managed)', does: 'starts the budget clock; reports a zero-tool-call fork and a missing exit artifact', covers: [['silent fork'], ['zero tool'], ['zero-tool'], ['exit artifact']] },
  { name: 'hook-show-me-hint.py', where: 'UserPromptSubmit', does: 'hints the show-me staging viewer when a prompt asks to see a file', covers: [['show-me'], ['show me', 'file'], ['staging viewer']] },
  { name: 'hook-crosstalk-nudge.py', where: 'UserPromptSubmit', does: 'nudges toward /crosstalk when a prompt reads like a cross-agent handoff', covers: [['crosstalk', 'nudge'], ['crosstalk', 'remind'], ['crosstalk', 'prompt'], ['handoff', 'prompt']] },
  { name: 'supabase-sql-verdict.py', where: 'PreToolUse mcp__claude_ai_Supabase__.*', does: 'judges every Supabase MCP call; only one keyed UPDATE or DELETE on a known workspace table, with RETURNING, passes', covers: [['execute_sql', 'write'], ['execute_sql', 'confirm'], ['execute_sql', 'destructive'], ['execute_sql', 'update'], ['execute_sql', 'delete'], ['update', 'returning'], ['delete', 'returning'], ['bare update'], ['bare delete'], ['destructive sql'], ['destructive-sql']] },
  { name: 'supabase-elicitation-accept.py', where: 'Elicitation', does: "auto-accepts the Supabase destructive-SQL dialog only when the session's recent Supabase verdicts all passed", covers: [['elicitation'], ['destructive', 'dialog'], ['auto-accept'], ['auto accept']] },
  { name: 'trap-annotator', where: 'mod, tool.call', does: 'notes a tool result that reads like proof but is not (Notion update no-ops, the reconcile request id, multi-statement execute_sql, first-write stamps)', covers: [['no-op'], ['silent success'], ['request id'], ['multi-statement']] },
  { name: 'subagent-model-guard', where: 'mod, agent.spawn', does: 'gives a spawn with no model Sonnet; toasts an Opus or Fable spawn or fork', covers: [['subagent', 'model'], ['agent', 'sonnet'], ['opus'], ['fable']] },
  { name: 'witness', where: 'mod', does: 'holds a bare Supabase UPDATE or DELETE with no RETURNING; keeps "done" claims pale until a read-back; tracks asks and the confirm tool', covers: [['read-back'], ['read back'], ['claim', 'verif'], ['done', 'verif'], ['returning']] },
  { name: 'estate-status', where: 'mod, disabled (folded into witness 0.3.0)', does: 'drew the estate ticket line; witness draws it now', covers: [['estate ticket'], ['ticket line']], disabled: true },
]

/** The guard or mod a hook candidate restates, or null; skills are never filtered here. */
export function coveringGuard(
  c: { kind: string; title: string; why: string },
  guards: readonly Guard[] = INSTALLED_GUARDS,
): Guard | null {
  if (c.kind !== 'hook') return null
  const text = `${c.title} ${c.why}`.toLowerCase()
  return guards.find(g => g.covers.some(terms => terms.every(t => text.includes(t)))) ?? null
}

const guardLine = (g: Guard): string => `- ${g.name} [${g.where}]: ${g.does}`

/** The side pass's prompt: candidates only on evidence, strict JSON back. */
export function candidatesPrompt(o: {
  friction: readonly Friction[]
  calls: readonly string[]
  existing: readonly Candidate[]
  /** Installed commands and skills (a field report): never proposed again as skills. */
  installed?: ReadonlyArray<{ name: string; description: string }>
  /** The guards to name (1.0): the estate's list where the estate is present, else none. */
  guards?: readonly Guard[]
}): string {
  const guards = (o.guards ?? INSTALLED_GUARDS).map(guardLine)
  const friction = o.friction.slice(-60).map(f => `- ${f.kind} ${one(f.key, 80)}: ${one(f.detail, 100)}`)
  const existing = o.existing.map(c => `- [${c.kind}] ${c.title}`)
  const installed = (o.installed ?? []).slice(0, MAX_INSTALLED).map(c => `- /${c.name}: ${one(c.description, INSTALLED_DESC)}`)
  return [
    'You read what one Claude Code session did: its recorded friction and a digest of its tool calls.',
    'Propose things that could be automated, ONLY where the log itself is the evidence:',
    '- HOOK: something that should happen, or be prevented, every time an event occurs (a guard, a check, a reminder). Evidence: friction that recurs, or a mistake corrected more than once.',
    '- SKILL: a multi-step manual sequence (three or more steps) done two or more times, that a named procedure could run. Evidence: the repeated calls.',
    'Never propose a skill that an installed command already covers, even if the session did the steps by hand.',
    'Never propose a hook or guard that an installed guard or mod already covers, even if the friction shows it firing: that is the guard working.',
    'Quote the log in "evidence". Skip anything already proposed. If nothing qualifies, return {"candidates": []}.',
    `At most ${MAX_CANDIDATES}. Reply with strict JSON only:`,
    '{"candidates": [{"kind": "hook" | "skill", "title": "<= 80 chars", "why": "<= 160 chars", "evidence": "<= 200 chars"}]}',
    '',
    'Already proposed:',
    ...(existing.length > 0 ? existing : ['- (none)']),
    '',
    'Installed commands:',
    ...(installed.length > 0 ? installed : ['- (none listed)']),
    '',
    'Installed guards and mods:',
    ...(guards.length > 0 ? guards : ['- (none listed)']),
    '',
    'Friction:',
    ...(friction.length > 0 ? friction : ['- (none)']),
    '',
    'Tool calls, oldest first:',
    ...(o.calls.length > 0 ? o.calls.map(c => `- ${c}`) : ['- (none)']),
  ].join('\n')
}

const candidateKey = (kind: string, title: string): string => `${kind}:${normalise(title)}`

/** The side pass's reply as candidates: tolerant of junk, validated, deduped, capped. */
export function parseCandidates(
  reply: string,
  existing: readonly Candidate[],
  at: number,
  guards: readonly Guard[] = INSTALLED_GUARDS,
): Candidate[] {
  const raw = parseJsonObject(reply)?.candidates
  if (!Array.isArray(raw)) return []
  const seen = new Set(existing.map(c => c.key))
  const out: Candidate[] = []
  for (const item of raw) {
    const x = item as { kind?: unknown; title?: unknown; why?: unknown; evidence?: unknown }
    if (x?.kind !== 'hook' && x?.kind !== 'skill') continue
    const title = one(typeof x.title === 'string' ? x.title : '', TITLE_CHARS)
    if (title === '') continue
    const key = candidateKey(x.kind, title)
    if (seen.has(key)) continue
    seen.add(key)
    const why = one(typeof x.why === 'string' ? x.why : '', WHY_CHARS)
    if (coveringGuard({ kind: x.kind, title, why }, guards) !== null) continue
    const evidence = one(typeof x.evidence === 'string' ? x.evidence : '', EVIDENCE_CHARS)
    out.push({ key, kind: x.kind, title, why, evidence, at, filed: false })
    if (out.length >= MAX_CANDIDATES) break
  }
  return out
}

export function mergeCandidates(existing: readonly Candidate[], fresh: readonly Candidate[]): Candidate[] {
  return [...existing, ...fresh].slice(-CANDIDATES_KEPT)
}

export function markFiled(candidates: readonly Candidate[], keys: readonly string[]): Candidate[] {
  const filed = new Set(keys)
  return candidates.map(c => (filed.has(c.key) ? { ...c, filed: true } : { ...c }))
}

/** Is a candidate pass due? Both the interval and enough new calls since the last one. */
export function shouldScan(o: { now: number; lastScanAt: number; newCalls: number }): boolean {
  return o.now - o.lastScanAt >= CANDIDATE_SCAN_MS && o.newCalls >= CANDIDATE_MIN_NEW_CALLS
}

const candidateLine = (c: Candidate): string =>
  `- [${c.kind}] ${c.title}${c.why ? ` - ${c.why}` : ''}${c.evidence ? ` (evidence: ${c.evidence})` : ''}`

/** The print's candidates section: this watch's proposals. */
export function candidatesSection(candidates: readonly Candidate[], since: number): string[] {
  const now = candidates.filter(c => c.at >= since)
  const head = ['### Hook and skill candidates', '']
  return now.length === 0 ? [...head, '- None proposed.'] : [...head, ...now.map(candidateLine)]
}

const FILE_HEAD = [
  '# Witness candidates',
  '',
  'Hook and skill candidates the witness companion proposed from friction and repeated',
  'sequences it saw. Proposals only: nothing here was built. Strike a line once it is ruled.',
  '',
].join('\n')

/** The running file with this watch's unfiled candidates appended; unchanged when there are none. */
export function appendCandidates(fileText: string, candidates: readonly Candidate[], o: { date: string; source: string }): string {
  const fresh = candidates.filter(c => !c.filed)
  if (fresh.length === 0) return fileText
  const base = fileText.trim() === '' ? FILE_HEAD : fileText.replace(/\s*$/, '\n')
  return `${base}\n## ${o.date} - ${one(o.source, 80)}\n\n${fresh.map(candidateLine).join('\n')}\n`
}

/** Where the running file lives: reports/ when the project has one, else beside the session logs. */
export function candidatesPath(cwd: string, hasReports: boolean): string {
  const root = cwd.replace(/\\/g, '/').replace(/\/+$/, '')
  return hasReports ? `${root}/reports/witness-candidates.md` : `${root}/.claude/witness-candidates.md`
}

files.hooks/carry.ts:
// Carry-over per session (1.2, ruled by Bradley 2026-10-09). Until now one slot per project held
// the leftover asks, rewritten after every turn: with several sessions open in one repository a
// new session took another LIVE session's undone asks as its own carried work, and whichever
// turn ended last overwrote the slot (seen live in S170, and named by a side agent's note).
// Ruled: each session keeps its leftovers in a slot of its own, and a starting session takes only
// the slots of sessions that have ENDED (written at their end, or untouched for hours: a crash),
// merged, one hop as before. A live session's slot is never taken and never overwritten. Pure.

import type { Ask } from '../types'
import { normalise } from './asks'

/** A slot untouched this long is a session that ended without saying so (a crash, a closed window). */
export const CARRY_STALE_MS = 6 * 60 * 60_000

/** One session's leftovers, under `carry:<project>:<session id>`. */
export type CarrySlot = { v: 2; sessionId: string; savedAt: number; ended: boolean; asks: Ask[] }

export const carryPrefix = (project: string): string => `carry:${project}:`
export const carrySlotKey = (project: string, sessionId: string): string => `${carryPrefix(project)}${sessionId}`

export function carrySlot(o: { sessionId: string; savedAt: number; ended: boolean; asks: readonly Ask[] }): CarrySlot {
  return { v: 2, sessionId: o.sessionId, savedAt: o.savedAt, ended: o.ended, asks: o.asks.map(a => ({ ...a })) }
}

/** A stored slot read back; null for anything else (the older single slot is a bare list, read apart). */
export function asCarrySlot(v: unknown): CarrySlot | null {
  if (v === null || typeof v !== 'object' || Array.isArray(v)) return null
  const o = v as Record<string, unknown>
  if (o.v !== 2 || typeof o.sessionId !== 'string' || typeof o.savedAt !== 'number' || !Number.isFinite(o.savedAt)) return null
  if (typeof o.ended !== 'boolean' || !Array.isArray(o.asks)) return null
  return carrySlot({ sessionId: o.sessionId, savedAt: o.savedAt, ended: o.ended, asks: o.asks as Ask[] })
}

/** Whether a starting session may take this slot: another session's, ended or gone stale. */
export function takeable(slot: CarrySlot, now: number, self: string): boolean {
  return slot.sessionId !== self && (slot.ended || now - slot.savedAt > CARRY_STALE_MS)
}

/** Leftovers from several ended sessions as one list, the same ask (by its text) once. */
export function mergeCarried(lists: ReadonlyArray<readonly Ask[]>): Ask[] {
  const seen = new Set<string>()
  const out: Ask[] = []
  for (const a of lists.flat()) {
    const k = normalise(a.text)
    if (seen.has(k)) continue
    seen.add(k)
    out.push({ ...a })
  }
  return out
}

