// Treat a barnacle (1.2, ruled by Bradley 2026-10-09 in a sibling session and relayed to this
// build): "i thought scrub would fix the barnacles by reading the ledger and proposing a fix".
// Beside each barnacle the pane offers TREAT and WASH. Wash is the old scrub (off the shell, no
// fix: a false alarm). Treat hands the session a prompt, as /tackle does: the barnacle's words, the
// friction records behind its key, and any repair pair or candidate on it. The session proposes
// ONE fix; the person accepts or rejects it. The barnacle comes off only when the session calls
// the `treated` tool for a barnacle the person put in treatment AND something has been written
// since (the fix landed); the scrub record then keeps the fix, so a regrowth says it did not hold.
// On demand only: nothing runs at /close or /start, and the witness makes no model call. Pure.

import type { Barnacle, Candidate, Friction, RepairPair } from '../types'
import { pairLine } from './immunity'

export const TREAT_HEADER = 'Treat a barnacle the witness keeps on its shell:'
export const TREATED_TOOL = 'mcp__witness__treated'
export const MAX_TREAT_RECORDS = 12
const FIX_MAX = 200

const oneLine = (s: string): string => s.replace(/\s+/g, ' ').trim()
const day = (at: number): string => (Number.isFinite(at) ? new Date(at).toISOString().slice(0, 16).replace('T', ' ') : '?')

/** Repair pairs that concern the barnacle's key: the same tool, the same epitope, or the same target. */
export function relatedPairs(key: string, pairs: readonly RepairPair[]): RepairPair[] {
  return pairs.filter(p => p.antigen.tool === key || p.key === key || p.antigen.target === key)
}

/** Candidates already proposed for it: a pair candidate on one of its pairs, or one naming the key. */
export function relatedCandidates(key: string, candidates: readonly Candidate[], pairs: readonly RepairPair[]): Candidate[] {
  const pairKeys = new Set(relatedPairs(key, pairs).map(p => `pair:${p.key}`))
  return candidates.filter(c => pairKeys.has(c.key) || `${c.title} ${c.evidence}`.includes(key))
}

const section = (title: string, lines: readonly string[]): string[] => [title, ...(lines.length > 0 ? lines : ['- (none)']), '']

/** The prompt the Treat button puts in the box: the evidence, and what to do with it. */
export function treatPrompt(o: {
  barnacle: Barnacle
  friction: readonly Friction[]
  pairs: readonly RepairPair[]
  candidates: readonly Candidate[]
}): string {
  const { key, text } = o.barnacle
  const records = o.friction
    .filter(f => f.key === key)
    .slice(-MAX_TREAT_RECORDS)
    .map(f => `- ${day(f.at)} ${f.kind}: ${oneLine(f.detail)}`)
  const pairs = relatedPairs(key, o.pairs).slice(-6).map(p => `- ${pairLine(p)}`)
  const proposed = relatedCandidates(key, o.candidates, o.pairs).map(c => `- [${c.kind}] ${c.title}${c.why ? ` - ${c.why}` : ''}`)
  return [
    TREAT_HEADER,
    `Barnacle \`${key}\`: ${oneLine(text)}`,
    '',
    ...section('What keeps going wrong, oldest first (the friction records behind it):', records),
    ...section('Repair pairs on it (a failed call and the call that cured it):', pairs),
    ...section('Already proposed for it:', proposed),
    'Propose ONE fix that would stop this recurring: a hook (a guard or check bound to an event), a skill line, a CLAUDE.md rule, or a code change. Say which records above it answers, and why it would hold. Make no change until the person accepts it.',
    `When the person has accepted it and the fix has landed, call the treated tool with key "${key}" and one line saying what the fix was. The barnacle then comes off; if the same friction comes back it grows back at once and says the fix did not hold.`,
    'If the person rejects it, leave the barnacle where it is. A false alarm is washed off in /barnacles.',
  ].join('\n')
}

/** The witness's own prompt, sent from the box: not mined for asks (its evidence is not the person's ask). */
export const isTreatPrompt = (text: string): boolean => text.trimStart().startsWith(TREAT_HEADER)

/** The treated tool's input: a key and a one-line fix, both present. */
export function parseTreated(input: unknown): { key: string; fix: string } | null {
  if (input === null || typeof input !== 'object') return null
  const { key, fix } = input as Record<string, unknown>
  if (typeof key !== 'string' || typeof fix !== 'string') return null
  const k = key.trim()
  const f = oneLine(fix).slice(0, FIX_MAX)
  return k === '' || f === '' ? null : { key: k, fix: f }
}

/** The shell with the barnacle `key` put in treatment at `at`; a new list. */
export function markTreating(barnacles: readonly Barnacle[], key: string, at: number): Barnacle[] {
  return barnacles.map(b => (b.key === key ? { ...b, treating: at } : { ...b }))
}

/**
 * Whether a `treated` call may take the barnacle off: only one the person put in treatment from
 * the pane (a human gesture starts it), and only once something has been written since (the fix
 * landed). The session cannot treat a barnacle on its own say.
 */
export function treatVerdict(barnacle: Barnacle | undefined, writesSince: number): { ok: true } | { ok: false; reason: string } {
  if (barnacle === undefined) return { ok: false, reason: 'No barnacle with that key is on the shell.' }
  if (barnacle.treating === undefined) {
    return { ok: false, reason: 'That barnacle was not put in treatment: only the person starts one, with Treat in /barnacles.' }
  }
  if (writesSince === 0) return { ok: false, reason: 'Nothing has been written since the treatment began, so no fix has landed yet.' }
  return { ok: true }
}

/** What the scrub record keeps for a treated barnacle: its words and the fix, said again if it regrows. */
export const treatedText = (b: Barnacle, fix: string): string => `${oneLine(b.text)} The fix did not hold: ${oneLine(fix)}`

export const TREATED_DESCRIPTION =
  'Witness: take a barnacle off the shell once its fix has landed. Only for a barnacle the person put in treatment from /barnacles (the Treat button), and only after the fix the person accepted was written. `key` is the barnacle key from the treat prompt; `fix` is one line saying what the fix was. If the same friction recurs, the barnacle grows back and says the fix did not hold.'

export const TREATED_SCHEMA = {
  type: 'object',
  properties: {
    key: { type: 'string', description: 'The barnacle key, exactly as the treat prompt gave it.' },
    fix: { type: 'string', description: 'One line: what the fix was (the hook, rule, skill line or change that landed).' },
  },
  required: ['key', 'fix'],
} as const

files.hooks/repair.ts:
// Repair pairs (1.2, Bradley 2026-10-09): a failed call, the next successful call on the same
// target, the diff between them, and the tokens every attempt before the cure cost. SQLSTATE is a
// free taxonomy; a failure's epitope is `code|target`. The diff sorts the cure: a changed CALL is
// a hook candidate, a changed ROUTE (another tool reaching the target) a skill line, no change at
// all is weather, logged and left alone. An epitope that recurs is immune memory. Pure: no $,
// no clock (time is the argument `at`), no argument is mutated.

import type { Antigen, OpenFailure, RepairDiff, RepairPair } from '../types'
import { cleanText } from './asks'
import { classify, normPath, notionIds } from './classify'
import { inputText } from './evidence'
import { tablesRead, tablesWritten } from './sql'

/** Main-session calls an open failure waits for its cure. */
export const REPAIR_WINDOW_CALLS = 40
/** Milliseconds an open failure waits for its cure after its last attempt. */
export const REPAIR_WINDOW_MS = 30 * 60_000
export const REPAIRS_KEPT = 100
export const PAIR_TEXT_MAX = 300
export const MAX_DIFF_TOKENS = 6
const TOKEN_MAX = 40
const FRAGMENT_MAX = 120
const REASON_MAX = 160

/** SQLSTATE read as a disease. */
export const KIND_BY_CODE: Readonly<Record<string, string>> = {
  '42703': 'undefined-column', '42P01': 'undefined-table',
  '42601': 'syntax', '23505': 'unique-violation',
  '42883': 'undefined-function', '23502': 'not-null-violation',
  '23503': 'foreign-key-violation', '23514': 'check-violation',
  '22P02': 'invalid-text', '42804': 'datatype-mismatch',
  '42501': 'insufficient-privilege', '42P07': 'duplicate-table',
  '42701': 'duplicate-column', '25P02': 'aborted-transaction',
}

type Obj = Record<string, unknown>
const isObj = (v: unknown): v is Obj => v !== null && typeof v === 'object' && !Array.isArray(v)
const unique = <T>(xs: readonly T[]): T[] => [...new Set(xs)]
const cut = (text: string, max: number): string => {
  const t = cleanText(text)
  return t.length <= max ? t : `${t.slice(0, max - 3)}...`
}
const kindOf = (code: string): string => (Object.prototype.hasOwnProperty.call(KIND_BY_CODE, code) ? (KIND_BY_CODE[code] as string) : code)

/** `mcp__claude_ai_Supabase__execute_sql` -> `execute_sql`; a plain tool name stays. */
export function shortTool(tool: string): string {
  const short = tool.slice(tool.lastIndexOf('__') + 2)
  return tool.includes('__') && short !== '' ? short : tool
}

// A SQLSTATE is five characters of [0-9A-Z] with a digit in them, behind one of the spellings
// an error comes in: `SQLSTATE 42703`, `(SQLSTATE 42703)`, `ERROR:  42703:`, `"code":"42703"`.
const STATE_RE = /(?:SQLSTATE|SQLState|sqlstate)\b[:=\s]*\(?\s*([0-9A-Z]{5})(?![0-9A-Za-z])|\bERROR:\s+([0-9A-Z]{5})(?![0-9A-Za-z])|\\?"code\\?"\s*:\s*\\?"([0-9A-Z]{5})(?![0-9A-Za-z])/g

/** The first SQLSTATE in an error text, or null. */
export function sqlState(text: string): string | null {
  for (const m of String(text ?? '').matchAll(STATE_RE)) {
    const code = m[1] ?? m[2] ?? m[3] ?? ''
    if (/\d/.test(code)) return code
  }
  return null
}

const CLASSES: ReadonlyArray<readonly [string, RegExp]> = [
  ['refused', /\b(?:denied|refused|refusing|refusal)\b|blocked by|not permitted|hook error|permission to use/i],
  ['string-not-found', /string to replace not found|old_string[\s\S]*?not found|not unique in the file/i],
  ['timeout', /timed out|timeout|ETIMEDOUT/i],
  ['not-found', /not found|ENOENT|no such file|does not exist|object_not_found/i],
  ['validation', /validation_error|InputValidationError|invalid input|could not be parsed|invalid_request/i],
]
const HTTP_RE = /(?:\bstatus["']?\s*:?\s*|\bHTTP(?:\/\d(?:\.\d)?)?\s*:?\s+)([45]\d{2})\b/i

/** A non-SQL failure's class, checked in order: the first that fits wins. */
export function errorClass(text: string): string {
  const t = String(text ?? '')
  const hit = CLASSES.find(([, re]) => re.test(t))
  if (hit !== undefined) return hit[0]
  const status = HTTP_RE.exec(t)?.[1]
  return status === undefined ? 'other' : `http-${status}`
}

/** The whole input as one cleaned line (inputText's pick, up to its own cap). */
function fullLine(input: unknown): string {
  if (typeof input === 'string') return cleanText(input)
  if (input === null || input === undefined) return ''
  if (typeof input !== 'object') return cleanText(String(input))
  try {
    // An Edit is told apart by what it replaced: without old_string a corrected Edit of the
    // same file would read as the same call (weather) when its content changed.
    const old = (input as Obj).old_string
    return cleanText(typeof old === 'string' ? `${inputText(input as Obj)} ${old}` : inputText(input as Obj))
  } catch {
    // An input JSON cannot serialise (a cycle, a BigInt) has no line; the call is still kept.
    return ''
  }
}

/** A call's input as one line of at most PAIR_TEXT_MAX characters. */
export const inputLine = (input: unknown): string => fullLine(input).slice(0, PAIR_TEXT_MAX)

/** Tokens a call and its result cost, estimated at four characters each. */
export const estTokens = (input: string, result: string): number => Math.ceil((input.length + result.length) / 4)

type TargetCall = { tool: string; input: unknown; writers?: RegExp | null }

const SENTINELS: ReadonlySet<string> = new Set(['*', 'git:*', 'migration:*', 'trigger:*', 'notion:new', 'trigger:new', 'notion:unknown'])
const KIND_PREFIX = /^(?:fn|git|migration|trigger|notion):/

/** A classified target without its kind prefix; null for a sentinel that names nothing. */
function bare(target: string): string | null {
  if (SENTINELS.has(target) || target.startsWith('other:')) return null
  const t = target.replace(KIND_PREFIX, '').toLowerCase()
  return t === '' ? null : t
}

/** The tables the call's `query` names, written and read, first-seen order. */
function queryTables(input: unknown): string[] {
  const q = isObj(input) ? input.query : undefined
  return typeof q === 'string' && q !== '' ? unique([...tablesWritten(q), ...tablesRead(q)]) : []
}

function classified(c: TargetCall): string[] {
  if (!isObj(c.input)) return []
  const { writes, reads } = classify({ tool: c.tool, input: c.input, resultText: '', isError: false, isReadOnly: false, writers: c.writers })
  return [...writes, ...reads].map((t) => t.target)
}

/** Whether the call sets out to write anything: a failed write is cured only by a write. */
export function writes(c: TargetCall): boolean {
  if (!isObj(c.input)) return false
  return classify({ tool: c.tool, input: c.input, resultText: '', isError: false, isReadOnly: false, writers: c.writers }).writes.length > 0
}

/** The normalised targets a call names, lower-case and deduped: files, tables, Notion ids. */
export function targetsOf(c: TargetCall): string[] {
  const tables = c.tool.includes('execute_sql') || c.tool.includes('apply_migration') ? queryTables(c.input) : []
  const all = [...classified(c), ...notionIds(fullLine(c.input)), ...tables]
  return unique(all.map(bare).filter((t): t is string => t !== null))
}

type CallText = TargetCall & { resultText: string }
type Where = { target: string; fragment: string }

const FILE_TOOLS: ReadonlySet<string> = new Set(['Edit', 'Write', 'Read', 'MultiEdit', 'NotebookEdit'])
const SHELLS: ReadonlySet<string> = new Set(['Bash', 'PowerShell', 'Monitor'])
const COLUMN_RE = /\bcolumn\s+((?:"[^"]*"|[\w$]+)(?:\.(?:"[^"]*"|[\w$]+))*)\s+(?:of relation\s+\S+\s+)?does not exist/i
const RELATION_RE = /\brelation\s+"?([\w$.]+)"?\s+does not exist/i

function columnOf(text: string): string | null {
  const col = COLUMN_RE.exec(text)?.[1]?.split('.').pop()?.replace(/"/g, '')
  return col === undefined || col === '' ? null : col
}

const named = (target: string): Where | null => (target === '' ? null : { target, fragment: target })

/** A SQL failure's target: table.column for an undefined column, the relation for an undefined table, else the first table. */
function sqlWhere(c: CallText, code: string): Where | null {
  const table = queryTables(c.input)[0] ?? ''
  const column = code === '42703' ? columnOf(c.resultText) : null
  if (column !== null) return { target: table === '' ? column : `${table}.${column}`, fragment: column }
  const relation = code === '42P01' ? RELATION_RE.exec(c.resultText)?.[1]?.toLowerCase() : undefined
  if (relation !== undefined) return named(relation)
  return table === '' ? null : { target: table, fragment: '' }
}

function fileWhere(input: unknown): Where | null {
  const o = isObj(input) ? input : {}
  const raw = [o.file_path, o.notebook_path].find((p): p is string => typeof p === 'string' && p.trim() !== '')
  return raw === undefined ? null : named(normPath(raw))
}

/** The target and fragment of a failing call: a file, a table and column, a Notion id, else its first target or its tool. */
function whereOf(c: CallText, state: string | null): Where {
  const none: Where = { target: c.tool, fragment: '' }
  if (FILE_TOOLS.has(c.tool)) return fileWhere(c.input) ?? none
  const sql = state === null ? null : sqlWhere(c, state)
  if (sql !== null) return sql
  if (c.tool.toLowerCase().includes('notion')) return named(notionIds(fullLine(c.input))[0] ?? '') ?? none
  return named(targetsOf(c)[0] ?? '') ?? none
}

const firstLine = (text: string): string => text.split(/\r?\n/).map(cleanText).find((l) => l !== '') ?? ''

/** What failed and on what: the antigen of one failing call. */
export function antigenOf(c: CallText): Antigen {
  // An MCP error arrives JSON-escaped, `column \"ask\" does not exist`: any run of backslashes before
  // a quote is undone first, or the column is never read (seen live, S170: the target fell back to
  // the table alone).
  const text = String(c.resultText ?? '').replace(/\\+"/g, '"')
  const state = sqlState(text)
  const code = state ?? errorClass(text)
  const where = whereOf({ ...c, resultText: text }, state)
  return {
    tool: c.tool,
    code,
    kind: kindOf(code),
    target: where.target,
    fragment: cut(where.fragment, FRAGMENT_MAX),
    reason: cut(firstLine(text), REASON_MAX),
  }
}

export const epitope = (a: Antigen): string => `${a.code}|${a.target}`

const clone = (o: OpenFailure): OpenFailure => ({ ...o, antigen: { ...o.antigen }, targets: [...o.targets] })

/** A measured context size, or undefined: a negative, non-finite or absent figure is no measurement. */
export const measured = (n: unknown): number | undefined => (typeof n === 'number' && Number.isFinite(n) && n >= 0 ? n : undefined)

/** Two optional sums: absent only while neither side was measured. */
const addOpt = (a: number | undefined, b: number | undefined): number | undefined =>
  a === undefined && b === undefined ? undefined : (a ?? 0) + (b ?? 0)

/**
 * A failing main-session call: opens a failure on its epitope, or adds an attempt to the one open.
 * `context` is the input the model was answered over to make this attempt (`$.session.usage()`):
 * every retry re-reads it, which the character estimate of `cost` leaves out (a side agent's note, S170).
 */
export function noteFailure(opens: readonly OpenFailure[], c: CallText & { at: number; context?: number }): OpenFailure[] {
  const antigen = antigenOf(c)
  // A shell command that failed with no known error on nothing it names is exploration (a grep
  // that found nothing), not an antigen: as a pair it would be cured by the next `ls` (the blind
  // verifier, S170). Bradley 2026-10-09: "a shell command that fails once is often exploration".
  if (SHELLS.has(c.tool) && antigen.code === 'other' && antigen.target === c.tool) return opens.map(clone)
  const key = epitope(antigen)
  const line = inputLine(c.input)
  const cost = estTokens(line, String(c.resultText ?? ''))
  const reread = measured(c.context)
  const touched = unique([...targetsOf(c), antigen.target])
  const last = { lastTool: c.tool, lastInput: line, lastFull: fullLine(c.input), lastAt: c.at, since: 0 }
  const kept = opens.map(clone)
  if (!kept.some((o) => o.key === key)) {
    const fresh: OpenFailure = { key, antigen, targets: touched, attempts: 1, cost, firstAt: c.at, write: writes(c), ...last }
    return [...kept, reread === undefined ? fresh : { ...fresh, reread }]
  }
  return kept.map((o) => {
    if (o.key !== key) return o
    const next: OpenFailure = { ...o, ...last, attempts: o.attempts + 1, cost: o.cost + cost, targets: unique([...o.targets, ...touched]) }
    const sum = addOpt(o.reread, reread)
    return sum === undefined ? next : { ...next, reread: sum }
  })
}

/** One more main-session call has passed: open failures past the window of calls or of time are dropped. */
export function age(opens: readonly OpenFailure[], at: number): OpenFailure[] {
  return opens
    .map((o) => ({ ...clone(o), since: o.since + 1 }))
    .filter((o) => o.since <= REPAIR_WINDOW_CALLS && at - o.lastAt <= REPAIR_WINDOW_MS)
}

const HEX32 = /^[0-9a-f]{32}$/

/**
 * Whether the call names the target. A Notion id or a path may sit anywhere in its input (a REST
 * call by shell on the page an MCP call failed on); a bare table name only through the call's own
 * parsed targets, so a diagnostic query that merely mentions the table cures nothing.
 */
function names(target: string, c: { targets: readonly string[] }, low: string, dashless: string): boolean {
  const t = target.toLowerCase()
  if (c.targets.includes(t)) return true
  if (t.length < 6) return false
  if (HEX32.test(t)) return whole(dashless, t)
  return t.includes('/') && whole(low, t)
}

/** A path or id character: a match running into one is part of a longer name. */
const NAME_CHAR = /[\w.$-]/

/** `needle` in `hay` standing whole: `src/a.ts` is not found in `src/a.tsx` (the verifier, S170). */
function whole(hay: string, needle: string): boolean {
  for (let i = hay.indexOf(needle); i >= 0; i = hay.indexOf(needle, i + 1)) {
    const before = i === 0 ? '' : hay.charAt(i - 1)
    const after = hay.charAt(i + needle.length)
    if (!NAME_CHAR.test(before) && !NAME_CHAR.test(after)) return true
  }
  return false
}

/**
 * Does a successful call land on this open failure's target? A failed write is cured only by a
 * call that writes (`writes` false refuses it): reading the file or the table is the
 * investigation, not the cure. Absent, the call is not judged on it.
 */
export function hits(open: OpenFailure, c: { tool: string; line: string; targets: readonly string[]; writes?: boolean }): boolean {
  if (open.write === true && c.writes === false) return false
  if (open.targets.every((t) => t === open.antigen.tool)) return c.tool === open.lastTool
  const low = c.line.toLowerCase().replace(/\\/g, '/')
  const dashless = low.replace(/-/g, '')
  return open.targets.some((t) => names(t, c, low, dashless))
}

// Identifier-like words, and quoted strings whole (what is inside them is not read again).
const TOKEN_RE = /'[^']*'|"[^"]*"|(?<![\w$])[A-Za-z_][\w.$-]*/g
const flat = (s: string): string => s.toLowerCase().replace(/\s+/g, ' ').trim()

function onlyIn(from: readonly string[], other: readonly string[]): string[] {
  const seen = new Set(other)
  return unique(from.filter((t) => !seen.has(t)))
    .slice(0, MAX_DIFF_TOKENS)
    .map((t) => t.slice(0, TOKEN_MAX))
}

/**
 * Where a cure differs from its failure. The tokens that went and came are read for a route
 * and a content diff alike; a `none` diff (the same call up to case and spacing) carries none.
 */
export function diffOf(failedTool: string, failed: string, cureTool: string, cured: string): RepairDiff {
  const where = failedTool !== cureTool ? 'route' : flat(failed) === flat(cured) ? 'none' : 'content'
  if (where === 'none') return { where, removed: [], added: [] }
  const before = failed.match(TOKEN_RE) ?? []
  const after = cured.match(TOKEN_RE) ?? []
  return { where, removed: onlyIn(before, after), added: onlyIn(after, before) }
}

function pairOf(o: OpenFailure, cureTool: string, cured: string, at: number, curedFull: string): RepairPair {
  // Compared whole: a fix past the 300 characters kept for display is still a diff (the verifier, S170).
  const diff = diffOf(o.lastTool, o.lastFull ?? o.lastInput, cureTool, curedFull)
  const reread = o.reread === undefined ? {} : { reread: o.reread }
  return {
    ...reread,
    key: o.key,
    antigen: { ...o.antigen },
    failures: o.attempts,
    failedTool: o.lastTool,
    failed: o.lastInput,
    cureTool,
    cured,
    diff,
    cost: o.cost,
    firstAt: o.firstAt,
    at,
    autoimmune: o.antigen.code === 'refused' && diff.where === 'none',
  }
}

/** A successful main-session call: every open failure it lands on becomes a repair pair. */
export function cure(
  opens: readonly OpenFailure[],
  c: { tool: string; input: unknown; at: number; writers?: RegExp | null },
): { opens: OpenFailure[]; pairs: RepairPair[] } {
  const full = fullLine(c.input)
  const line = full.slice(0, PAIR_TEXT_MAX)
  const probe = { tool: c.tool, line: full, targets: targetsOf(c), writes: writes(c) }
  const landed = opens.map((o) => hits(o, probe))
  return {
    opens: opens.filter((_, i) => !landed[i]).map(clone),
    pairs: opens.filter((_, i) => landed[i]).map((o) => pairOf(o, c.tool, line, c.at, full)),
  }
}

files.hooks/sonar.ts:
// The sonar (1.2): every running witness session (a pod) writes a heartbeat file and reads the
// others', so a pod knows who else is live, where two have written the same file, and where a
// /hand can go. Pure functions over plain data: no clock, no ids made here, no files read.
// Two lines are drawn here: a collision alert fires only on overlapping paths in a place the
// pods share; and a hand the person typed may start an idle pod's turn, while one a Claude
// session wrote only waits for the person's Enter (isForgedHand and touchesSonar guard that).

import type { Beat, Hand, Overlap, PodState, PodWrite } from '../types'
import { normPath } from './classify'
import { personRef } from './config'

export const BEAT_MS = 30_000
export const LIVE_MS = 120_000
export const OVERLAP_MS = 30 * 60_000
export const MAX_BEAT_WRITES = 20
export const MAX_GOALS = 3
export const GOAL_CHARS = 90
export const HAND_TEXT_MAX = 2000
/** The folders of `~/.claude` every session shares (and `CLAUDE.md` beside them). */
export const SHARED_CLAUDE_DIRS = ['rules', 'skills', 'tools', 'agents'] as const
/** What every hand envelope starts with, and what a model's own message may never carry. */
export const HAND_TAG = '[witness hand'

const SONAR_FOLDER = '.claude/state/witness-sonar'
const SONAR_WORD = 'witness-sonar'
const PREVIEW_CHARS = 80
const MIN_ID_PREFIX = 4
const STATES: readonly string[] = ['working', 'idle', 'ended']

const slashed = (s: string): string => s.replace(/\\/g, '/')
/** A drive-letter or rooted path, as the ledger normalises it. */
const ABSOLUTE = /^(?:[a-z]:\/|\/)/i
/** The project key's rule: forward slashes, no trailing slash, lower-case. */
const lower = (s: string): string => slashed(s).replace(/\/+$/, '').toLowerCase()
const oneLine = (s: string): string => s.replace(/\s+/g, ' ').trim()
const cut = (s: string, max: number): string => (s.length <= max ? s : `${s.slice(0, max - 3)}...`)
const byNewest = <T extends { at: number }>(xs: readonly T[]): T[] => [...xs].sort((a, b) => b.at - a.at)
const under = (path: string, dir: string): boolean => dir !== '' && path.startsWith(`${dir}/`)
const isObj = (v: unknown): v is Record<string, unknown> => v !== null && typeof v === 'object' && !Array.isArray(v)
const isNum = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v)
const str = (v: unknown): string => (typeof v === 'string' ? v : '')

function parseJson(text: string): Record<string, unknown> | null {
  let v: unknown = null
  try {
    v = JSON.parse(text)
  } catch {
    v = null // not JSON: every caller refuses it
  }
  return isObj(v) ? v : null
}

/** `<home>/.claude/state/witness-sonar`; null when the home is unknown. */
export function sonarDir(home: string | undefined): string | null {
  const h = slashed((home ?? '').trim()).replace(/\/+$/, '')
  return h === '' ? null : `${h}/${SONAR_FOLDER}`
}

export const safeId = (id: string): string => id.replace(/[^A-Za-z0-9._-]/g, '_')

/** The UTC day, `YYYY-MM-DD`. */
export function dayOf(at: number): string {
  const t = Number.isFinite(at) && Math.abs(at) <= 8.64e15 ? at : 0
  return new Date(t).toISOString().slice(0, 10)
}

/** The folder is the day of the BEAT, so a live session always has a fresh file in today's folder. */
export const beatPath = (dir: string, at: number, sessionId: string): string =>
  `${dir}/${dayOf(at)}/${safeId(sessionId)}.json`

/** The days a sweep reads: today and yesterday, UTC. */
export const beatDays = (now: number): string[] => [dayOf(now), dayOf(now - 86_400_000)]

export const handsDir = (dir: string, to: string): string => `${dir}/hands/${safeId(to)}`
export const handPath = (dir: string, to: string, id: string): string => `${handsDir(dir, to)}/${safeId(id)}.json`

const cleanGoals = (goals: readonly string[]): string[] =>
  goals
    .map(oneLine)
    .filter((g) => g !== '')
    .slice(0, MAX_GOALS)
    .map((g) => cut(g, GOAL_CHARS))

const lastSegment = (path: string): string => slashed(path).replace(/\/+$/, '').split('/').pop() ?? ''

export function makeBeat(o: {
  sessionId: string
  cwd: string
  root: string | null
  startedAt: number
  now: number
  state: PodState
  goals: readonly string[]
  asks: string
  writes: readonly PodWrite[]
  notion?: readonly PodWrite[]
  tables?: readonly PodWrite[]
}): Beat {
  const root = o.root === null ? '' : lower(o.root)
  // The Notion pages and tables written (1.2, ruled 2026-10-09): additive fields on version 1.
  const more = {
    ...(o.notion === undefined ? {} : { notion: o.notion.slice(0, MAX_BEAT_WRITES).map((w) => ({ path: w.path, at: w.at })) }),
    ...(o.tables === undefined ? {} : { tables: o.tables.slice(0, MAX_BEAT_WRITES).map((w) => ({ path: w.path, at: w.at })) }),
  }
  return {
    ...more,
    format: 'witness-sonar',
    version: 1,
    sessionId: o.sessionId,
    repo: lower(o.cwd),
    root: root === '' ? null : root,
    name: lastSegment(o.cwd),
    startedAt: o.startedAt,
    beatAt: o.now,
    state: o.state,
    goals: cleanGoals(o.goals),
    asks: o.asks,
    writes: o.writes.slice(0, MAX_BEAT_WRITES).map((w) => ({ path: w.path, at: w.at })),
  }
}

export const beatFile = (b: Beat): string => JSON.stringify(b)

function podWrites(raw: unknown): PodWrite[] {
  if (!Array.isArray(raw)) return []
  const out: PodWrite[] = []
  for (const w of raw as unknown[]) {
    if (isObj(w) && typeof w.path === 'string' && w.path !== '' && isNum(w.at)) out.push({ path: w.path, at: w.at })
    if (out.length === MAX_BEAT_WRITES) break
  }
  return out
}

/**
 * A heartbeat file as another session wrote it: unknown fields dropped, malformed goals and
 * writes filtered, counts bounded; null on anything untrustworthy. A higher version is refused.
 */
export function parseBeat(text: string): Beat | null {
  const j = parseJson(text)
  if (j === null || j.format !== 'witness-sonar' || j.version !== 1) return null
  const { sessionId, startedAt, beatAt, state } = j
  if (typeof sessionId !== 'string' || sessionId === '') return null
  if (!isNum(startedAt) || !isNum(beatAt) || typeof state !== 'string' || !STATES.includes(state)) return null
  const goals = Array.isArray(j.goals) ? (j.goals as unknown[]).filter((g): g is string => typeof g === 'string') : []
  const more = {
    ...(Array.isArray(j.notion) ? { notion: podWrites(j.notion) } : {}),
    ...(Array.isArray(j.tables) ? { tables: podWrites(j.tables) } : {}),
  }
  return {
    ...more,
    format: 'witness-sonar',
    version: 1,
    sessionId,
    repo: str(j.repo),
    root: typeof j.root === 'string' ? j.root : null,
    name: str(j.name),
    startedAt,
    beatAt,
    state: state as PodState,
    goals: cleanGoals(goals),
    asks: str(j.asks),
    writes: podWrites(j.writes),
  }
}

/**
 * The file writes worth putting in a beat: files only, no wildcard (a test run's `*`), inside
 * the overlap window, one per path at its newest time, newest first.
 */
export function recentWrites(writes: ReadonlyArray<{ kind: string; target: string; at: number }>, now: number): PodWrite[] {
  const newest = new Map<string, number>()
  for (const w of writes) {
    // Absolute paths only: a shell write is read best-effort, and `$out` or `$sp/hooks` (seen in
    // the first live beat, S170) names a variable, not a file another pod could also write.
    if (w.kind !== 'file' || !ABSOLUTE.test(w.target) || w.target.includes('*') || w.target.includes('$')) continue
    if (!Number.isFinite(w.at) || w.at < now - OVERLAP_MS) continue
    const seen = newest.get(w.target)
    if (seen === undefined || w.at > seen) newest.set(w.target, w.at)
  }
  return byNewest([...newest].map(([path, at]) => ({ path, at }))).slice(0, MAX_BEAT_WRITES)
}

const podOrder = (a: Beat, b: Beat): number => {
  const [an, bn] = [a.name.toLowerCase(), b.name.toLowerCase()]
  if (an !== bn) return an < bn ? -1 : 1
  if (a.startedAt !== b.startedAt) return a.startedAt - b.startedAt
  return a.sessionId < b.sessionId ? -1 : a.sessionId > b.sessionId ? 1 : 0
}

/**
 * The other pods that are live. Each session's newest beat decides (an `ended` beat is not
 * undone by an older `working` one); then stale, ended and own beats drop. Sorted by name.
 */
export function livePods(beats: readonly Beat[], o: { now: number; self: string }): Beat[] {
  const newest = new Map<string, Beat>()
  for (const b of beats) {
    const seen = newest.get(b.sessionId)
    if (seen === undefined || b.beatAt > seen.beatAt) newest.set(b.sessionId, b)
  }
  return [...newest.values()]
    .filter((b) => b.beatAt >= o.now - LIVE_MS && b.state !== 'ended' && b.sessionId !== o.self)
    .sort(podOrder)
}

/** Whether two pods can both reach `path`: inside either repo, or a shared `~/.claude` place. */
export function sharedPlace(path: string, roots: ReadonlyArray<string | null>, home: string | null): boolean {
  const p = normPath(path)
  if (roots.some((r) => r !== null && under(p, normPath(r)))) return true
  const h = home === null ? '' : normPath(home)
  if (h === '') return false
  return p === `${h}/.claude/claude.md` || SHARED_CLAUDE_DIRS.some((d) => under(p, `${h}/.claude/${d}`))
}

function newestByPath(writes: readonly PodWrite[], floor: number): Map<string, number> {
  const out = new Map<string, number>()
  for (const w of writes) {
    const k = normPath(w.path)
    if (w.at >= floor && w.at > (out.get(k) ?? Number.NEGATIVE_INFINITY)) out.set(k, w.at)
  }
  return out
}

/** The files this pod and another both wrote lately, in a place they share; one per path and peer. */
export function overlaps(o: {
  mine: readonly PodWrite[]
  myRoot: string | null
  pods: readonly Beat[]
  home: string | null
  now: number
}): Overlap[] {
  const floor = o.now - OVERLAP_MS
  const mine = o.mine.filter((w) => w.at >= floor)
  const found = new Map<string, Overlap>()
  for (const pod of o.pods) {
    const theirs = newestByPath(pod.writes, floor)
    for (const m of mine) {
      const key = normPath(m.path)
      const theirAt = theirs.get(key)
      if (theirAt === undefined || !sharedPlace(m.path, [o.myRoot, pod.root], o.home)) continue
      const id = `${key}\u0000${pod.sessionId}`
      const at = Math.max(m.at, theirAt)
      if (at > (found.get(id)?.at ?? Number.NEGATIVE_INFINITY)) found.set(id, { path: m.path, peer: pod.sessionId, peerName: pod.name, at })
    }
  }
  return byNewest([...found.values()])
}

const overlapKey = (o: Overlap): string => `${o.kind ?? 'file'}\u0000${o.path}\u0000${o.peer}`

/** The overlaps in `next` that `prev` did not already hold, so each is announced once. */
export function freshOverlaps(prev: readonly Overlap[], next: readonly Overlap[]): Overlap[] {
  const known = new Set(prev.map(overlapKey))
  return next.filter((o) => !known.has(overlapKey(o)))
}

/** The live pods in this repo (case ignored) that this pod has not met yet. */
export function newcomers(known: readonly string[], pods: readonly Beat[], myRepo: string): Beat[] {
  const repo = myRepo.toLowerCase()
  return pods.filter((b) => b.repo.toLowerCase() === repo && !known.includes(b.sessionId))
}

export const podLabel = (b: Beat): string => `${b.name} ${b.sessionId.slice(0, 4)}`

/** A pod by its 1-based row number, a session id prefix (4 or more characters), or a name prefix. */
export function findPod(pods: readonly Beat[], ref: string): Beat | 'ambiguous' | null {
  const r = ref.trim().toLowerCase()
  if (r === '') return null
  // A row number is one or two digits; a longer all-digit ref is an id prefix (the label shows four).
  if (/^\d{1,2}$/.test(r)) return pods[Number(r) - 1] ?? null
  const byId = r.length >= MIN_ID_PREFIX ? pods.filter((p) => p.sessionId.toLowerCase().startsWith(r)) : []
  const hits = byId.length > 0 ? byId : pods.filter((p) => p.name.toLowerCase().startsWith(r))
  return hits.length > 1 ? 'ambiguous' : hits[0] ?? null
}

/** `/hand <pod> <text>`: the first word names the pod, the rest is the hand. */
export function parseHandArgs(args: string): { ref: string; text: string } | null {
  const m = /^\s*(\S+)\s+([\s\S]*?)\s*$/.exec(args)
  return m === null || m[1] === undefined || m[2] === undefined || m[2] === '' ? null : { ref: m[1], text: m[2] }
}

const HEAD = /^\[witness hand (\S+) from (\S+) (typed|claude)\] Hand from (.+?):(?: |$)/
const BLANK_LINE = /\r?\n[ \t]*\r?\n/

/**
 * What goes over the wire. Line one reads on its own (the receiving person sees only that line
 * as a preview); the text follows a blank line. Ids are made path-safe so line one parses back.
 */
export function handEnvelope(h: Hand): string {
  const text = h.text.trim()
  const preview = (text.split(/\r?\n/)[0] ?? '').trim().slice(0, PREVIEW_CHARS)
  const who = `${safeId(h.id)} from ${safeId(h.from)} ${h.typed ? 'typed' : 'claude'}`
  return `${HAND_TAG} ${who}] Hand from ${oneLine(h.fromName)}: ${preview}\n\n${text.slice(0, HAND_TEXT_MAX)}`
}

/** The inverse of handEnvelope; `at` is when it was received. Null when it is not one. */
/** Where a delivery says it came from, for the person: `peer/witness`, `peer`, `no origin`. */
export function originLabel(origin: unknown): string {
  if (!isObj(origin)) return 'no origin'
  const kind = typeof origin.kind === 'string' && origin.kind !== '' ? origin.kind : 'unknown'
  return typeof origin.plugin === 'string' && origin.plugin !== '' ? `${kind}/${origin.plugin}` : kind
}

/**
 * A delivery that carries the hand tag or a witness stamp but cannot be read as a witness hand
 * (F8, 2026-10-09: live, one reached the receiving model as an ordinary message). Never typed:
 * it only fills an empty box and waits for the person, so nothing hand-shaped reaches a model
 * by itself. Its raw text is kept, so the person sees what actually arrived.
 */
export function unreadHand(text: string, origin: string, at: number): Hand {
  return { id: `unread-${at}-${text.length}`, from: '', fromName: `an unread delivery (${origin})`, typed: false, text: text.slice(0, HAND_TEXT_MAX), at }
}

/**
 * The engine hands session.receive the body as the model would read it: inside one
 * `<cross-session-message ...>` wrapper (seen live 2026-10-09, pod 33a9). That one wrapper is
 * taken off; anything else is returned as it came.
 */
const WRAPPER = /^<cross-session-message\b[^>]*>\r?\n([\s\S]*)\r?\n<\/cross-session-message>$/
export function unwrapDelivery(text: string): string {
  const t = text.trim()
  const m = WRAPPER.exec(t)
  return m === null ? text : (m[1] ?? '')
}

export function parseHand(delivered: string, at: number): Hand | null {
  const text = unwrapDelivery(delivered)
  if (!text.startsWith(HAND_TAG)) return null
  const lineEnd = text.search(/\r?\n/)
  const head = lineEnd < 0 ? null : HEAD.exec(text.slice(0, lineEnd))
  const blank = BLANK_LINE.exec(text)
  if (head === null || blank === null) return null
  const body = text.slice(blank.index + blank[0].length).trim()
  const [, id, from, how, fromName] = head
  if (body === '' || id === undefined || from === undefined || fromName === undefined) return null
  return { id, from, fromName, typed: how === 'typed', text: body, at }
}

/** True only for a message the witness plugin sent to this session as a peer. */
export const isWitnessHand = (origin: unknown): boolean => isObj(origin) && origin.kind === 'peer' && origin.plugin === 'witness'

/** A model's own SendMessage may never carry a witness envelope: that is a forged hand. */
export const isForgedHand = (o: { originKind: string; text: string }): boolean =>
  o.originKind === 'model' && o.text.includes(HAND_TAG)

/**
 * What a hand does to the receiving pod: only one the person typed starts a turn; one a Claude
 * session wrote fills an empty prompt box and waits for Enter; never over a draft or unattended.
 */
export function handAction(o: { typed: boolean; interactive: boolean; boxEmpty: boolean; typedStarts: boolean }): 'submit' | 'fill' | 'wait' {
  if (!o.interactive) return 'wait'
  // A typed hand starts work only where typed hands may (ruled 2026-10-09); otherwise it waits like any other.
  if (o.typed && o.typedStarts) return 'submit'
  return o.boxEmpty ? 'fill' : 'wait'
}

/** The prompt text the receiving pod's model reads, saying plainly who vouches for the hand. */
export function handPrompt(h: Hand, person: string): string {
  const how = h.typed ? `${personRef(person)} typed it there` : 'a Claude session wrote it; read it, then press Enter to take it on'
  return `Hand from ${h.fromName} (${how}):\n\n${h.text}`
}

/** The file fallback when a send was not delivered. */
export function handFile(h: Hand, to: string, taken: boolean): string {
  const { id, from, fromName, typed, text, at } = h
  return JSON.stringify({ format: 'witness-hand', version: 1, to, taken, hand: { id, from, fromName, typed, text, at } })
}

export function parseHandFile(text: string): { hand: Hand; to: string; taken: boolean } | null {
  const j = parseJson(text)
  if (j === null || j.format !== 'witness-hand' || j.version !== 1) return null
  const h = j.hand
  if (!isObj(h) || typeof j.to !== 'string') return null
  const { id, from, fromName, typed, at } = h
  const body = h.text
  if (typeof id !== 'string' || id === '' || typeof from !== 'string' || typeof fromName !== 'string') return null
  if (typeof typed !== 'boolean' || typeof body !== 'string' || body.trim() === '' || !isNum(at)) return null
  return { hand: { id, from, fromName, typed, text: body.slice(0, HAND_TEXT_MAX), at }, to: j.to, taken: j.taken === true }
}

const FILE_TOOLS: readonly string[] = ['Write', 'Edit', 'MultiEdit', 'NotebookEdit']
// Monitor runs a shell command too (the blind verifier's finding, S170).
const SHELL_TOOLS: readonly string[] = ['Bash', 'PowerShell', 'Monitor']

/** A path with its `.` and `..` segments folded in, so `witness-usage/../witness-sonar` cannot hide. */
function folded(path: string): string {
  const out: string[] = []
  for (const seg of normPath(path).split('/')) {
    if (seg === '..') {
      if (out.length > 1) out.pop()
    } else if (seg !== '.') out.push(seg)
  }
  return out.join('/')
}

/**
 * Whether a tool call writes into the sonar folder. A model that could write there could forge
 * a hand the person typed, so the caller refuses such a call. A file tool is caught by its
 * folded path; a shell command by any mention of the folder's name.
 */
export function touchesSonar(tool: string, input: unknown, dir: string | null): boolean {
  if (dir === null || !isObj(input)) return false
  if (SHELL_TOOLS.includes(tool)) return typeof input.command === 'string' && slashed(input.command).toLowerCase().includes(SONAR_WORD)
  if (!FILE_TOOLS.includes(tool)) return false
  const root = normPath(dir)
  return [input.file_path, input.notebook_path].some((p) => {
    if (typeof p !== 'string') return false
    const f = folded(p)
    return under(f, root) || f.split('/').includes(SONAR_WORD)
  })
}

